-- Regenerate after changing the synthetic data model or defect profile.

-- Stage 1 of 2 in the cleansing layer: repair every column and
-- assess every row, once. `stg_` and `qtn_` both read from here,
-- so the expensive parsing is not paid for twice.

with source as (
    select * from {{ source('lake_dimensions', 'dim_site') }}
),

-- Stage 1: repair. Trim, case-fold, parse numbers out of
-- locale-formatted text, range-check timestamps.
cleansed as (
    select
        {{ clean_code('site_id') }} as site_id,
        {{ fix_mojibake('site_name') }} as site_name,
        {{ clean_code('country_code') }} as country_code,
        {{ fix_mojibake('province') }} as province,
        {{ fix_mojibake('city') }} as city,
        {{ fix_mojibake('urban_class') }} as urban_class,
        {{ clean_measure('latitude') }} as latitude,
        {{ clean_measure('longitude') }} as longitude,
        {{ fix_mojibake('site_type') }} as site_type,
        {{ fix_mojibake('ownership_model') }} as ownership_model,
        try_cast(on_national_route as boolean) as on_national_route,
        {{ clean_integer('site_key') }} as site_key,
        {{ clean_integer('forecourt_lanes') }} as forecourt_lanes,
        try_cast(has_convenience as boolean) as has_convenience,
        try_cast(has_qsr as boolean) as has_qsr,
        try_cast(has_car_wash as boolean) as has_car_wash,
        try_cast(has_ev_charging as boolean) as has_ev_charging,
        try_cast(has_solar as boolean) as has_solar,
        try_cast(has_lpg as boolean) as has_lpg,
        try_cast(is_24_hour as boolean) as is_24_hour,
        {{ clean_timestamp('opened_date') }} as opened_date,
        {{ fix_mojibake('site_status') }} as site_status,
        {{ clean_measure('demand_index') }} as demand_index,
        {{ clean_timestamp('effective_from_date') }} as effective_from_date,
        {{ clean_timestamp('effective_to_date') }} as effective_to_date,
        try_cast(is_current as boolean) as is_current,
        {{ clean_integer('scd_version') }} as scd_version,
        {{ fix_mojibake('record_source') }} as record_source,
        {{ clean_timestamp('dw_load_ts') }} as dw_load_ts,
        {{ fix_mojibake('dw_hash_diff') }} as dw_hash_diff
    from source
),

-- Stage 2: assess. One boolean per rule, so a quarantined
-- row records exactly why it was rejected.
assessed as (
    select
        *,
        (site_id is not null) as _dq_site_id_present,
        (coalesce(_dq_site_id_present, false)) as _dq_is_valid,
        concat_ws(',',
            case when not coalesce(_dq_site_id_present, false) then 'site_id_present' end
        ) as _dq_failed_rules
    from cleansed
)

select
    *,
    {{ cleansing_layer_columns() }}
from assessed
